import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/N-OF-CASES.md","filePath":"manual-en/N-OF-CASES.md","lastUpdated":1785684581000}'),c={name:"manual-en/N-OF-CASES.md"};function d(r,e,n,i,l,S){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h3 id="_13-2-n-of-cases" tabindex="-1">13.2 N OF CASES <a class="header-anchor" href="#_13-2-n-of-cases" aria-label="Permalink to &quot;13.2 N OF CASES&quot;">​</a></h3><pre><code>N [OF CASES] num_of_cases [ESTIMATED].
</code></pre><p><code>N OF CASES</code> limits the number of cases processed by any procedures that follow it in the command stream. <code>N OF CASES 100</code>, for example, tells PSPP to disregard all cases after the first 100.</p><p>When <code>N OF CASES</code> is specified after <code>TEMPORARY</code>, it affects only the next procedure (see <a href="./TEMPORARY">TEMPORARY</a>). Otherwise, cases beyond the limit specified are not processed by any later procedure.</p><p>If the limit specified on <code>N OF CASES</code> is greater than the number of cases in the active dataset, it has no effect.</p><p>When <code>N OF CASES</code> is used along with <code>SAMPLE</code> or <code>SELECT IF</code>, the case limit is applied to the cases obtained after sampling or case selection, regardless of how <code>N OF CASES</code> is placed relative to <code>SAMPLE</code> or <code>SELECT IF</code> in the command file. Thus, the commands <code>N OF CASES 100</code> and <code>SAMPLE .5</code> both randomly sample approximately half of the active dataset’s cases, then select the first 100 of those sampled, regardless of their order in the command file.</p><p><code>N OF CASES</code> with the <code>ESTIMATED</code> keyword gives an estimated number of cases before <code>DATA LIST</code> or another command to read in data. <code>ESTIMATED</code> never limits the number of cases processed by procedures. PSPP currently does not make use of case count estimates.</p>`,7)])])}const f=o(c,[["render",d]]);export{p as __pageData,f as default};
